def needs_decoding(url: str) -> bool:
    """Check if URL contains percent-encoded characters."""
    return '%' in url and any(c in url for c in '0123456789ABCDEF')

def safe_decode_url(url: str) -> str:
    """Safely decode URL, handling already-decoded or malformed URLs."""
    if not needs_decoding(url):
        return url

    try:
        decoded = unquote(url, encoding='utf-8')
        # Verify decoding produced valid UTF-8
        decoded.encode('utf-8')
        return decoded
    except (UnicodeDecodeError, UnicodeEncodeError):
        return url  # Return original if issues

