 * Convert citation placeholders into clickable links
 * @param {string} content - The markdown/HTML content with citation placeholders
 * @param {Object} citationMap - Map of doc_id to citation info {author, date, card_type, card_index}
 * @returns {string} Content with citations as clickable links
 */
function renderCitationsAsLinks(content, citationMap) {
    if (!citationMap || Object.keys(citationMap).length === 0) {
        return content;
    }

    // Pattern to match: (doc_XXX, qa-N) or (doc_XXX, summary)
    const citationPattern = /\(([a-f0-9]+),\s*(qa-\d+|summary)\)/gi;

    return content.replace(citationPattern, (match, docId, refType) => {
        // Look up citation info in the map
        const citationInfo = citationMap[docId];

        if (!citationInfo) {
            // If no mapping found, return original text
            return match;
        }

        // Build display text: (Author, Month Year)
        const displayText = `(${citationInfo.author}, ${citationInfo.date})`;

        // Build target card ID: sum-{index} or qa-{index}
        const cardId = `${citationInfo.card_type}-${citationInfo.card_index}`;

        // Return as clickable link
        return `<a href="#${cardId}" class="citation-link" data-card-id="${cardId}">${displayText}</a>`;
    });
}

