def decode_url_for_display(url: str) -> str:
    """
    Decode percent-encoded URLs for human-readable display.
    Handles Arabic/Hebrew characters and other international characters.

    Args:
        url: The percent-encoded URL string

    Returns:
        Human-readable decoded URL string
    """
    try:
        return unquote(url)
    except Exception as e:
        logger.warning(f"Failed to decode URL: {url}, error: {e}")
        return url  # Return original if decoding fails


def build_citation_map(retrieved_docs: List, retrieved_qa: Optional[List] = None) -> Dict[str, Dict]:
    """
    Build a citation map for converting (doc_id, qa-N) placeholders to (Author, Date) format.

    Args:
        retrieved_docs: List of DocumentResult objects (summaries)
        retrieved_qa: Optional list of QA items

    Returns:
        Dictionary mapping document_id to citation info:
        {
            "doc_id": {
                "author": "Author Name",
                "date": "Month Year",
                "card_type": "sum" or "qa",
                "card_index": 0  # Index in the card list
            }
        }
    """
    citation_map = {}

    # Process summary documents
    for index, doc in enumerate(retrieved_docs):
        doc_id = doc.document_id if hasattr(doc, 'document_id') else doc.get('document_id')
        doc_metadata = doc.doc_metadata if hasattr(doc, 'doc_metadata') else doc.get('doc_metadata', {})

        # Extract author (try multiple fields)
        author = doc_metadata.get('author') or doc_metadata.get('publisher') or 'Unknown'

        # Extract and format date
        pub_date = doc_metadata.get('publication_date') or doc_metadata.get('creation_date')
        if pub_date:
            try:
                # Parse date and format as "Month Year"
                date_obj = datetime.fromisoformat(pub_date.replace('Z', '+00:00'))
                formatted_date = date_obj.strftime('%B %Y')
            except Exception:
                formatted_date = pub_date  # Use as-is if parsing fails
        else:
            formatted_date = 'N/A'

        citation_map[doc_id] = {
            "author": author,
            "date": formatted_date,
            "card_type": "sum",
            "card_index": index
        }

    # Process QA items
    if retrieved_qa:
        for index, qa in enumerate(retrieved_qa):
            doc_id = qa.get('document_id', 'unknown')
            qa_metadata = qa.get('doc_metadata', {})

            # Extract author
            author = qa_metadata.get('author') or qa_metadata.get('publisher') or 'Unknown'

            # Extract and format date
            pub_date = qa_metadata.get('publication_date') or qa_metadata.get('creation_date')
            if pub_date:
                try:
                    date_obj = datetime.fromisoformat(pub_date.replace('Z', '+00:00'))
                    formatted_date = date_obj.strftime('%B %Y')
                except Exception:
                    formatted_date = pub_date
            else:
                formatted_date = 'N/A'

            citation_map[doc_id] = {
                "author": author,
                "date": formatted_date,
                "card_type": "qa",
                "card_index": index
            }

    return citation_map

